func divide(a, b int) (result int, err error) {
  if b == 0 {
    err = fmt.Errorf("القسمة على صفر")
    return   // naked return: يعيد result و err الحاليّين
  }
  result = a / b
  return
}

r, err := divide(10, 2)
fmt.Println(r, err)   // 5 <nil>

func process() {
  fmt.Println("بداية")
  defer fmt.Println("أولاً يُكتب — آخر ما يُطبع")
  defer fmt.Println("ثانيًا يُكتب — يُطبع قبل الأول")
  fmt.Println("نهاية الدالة")
}
// الناتج:
// بداية
// نهاية الدالة
// ثانيًا يُكتب — يُطبع قبل الأول
// أولاً يُكتب — آخر ما يُطبع

func greet(name string) {
  fmt.Println("مرحبًا", name)
}

func main() {
  go greet("براء")       // يعمل بالتوازي
  go greet("سارة")       // يعمل بالتوازي أيضًا
  time.Sleep(time.Second)  // بدون هذا قد ينهي main قبل طباعتهما
}

syntax:
select {
case v := <-ch1:
  // ...
case ch2 <- value:
  // ...
default:
  // اختياري — ينفَّذ إن لم تجهز أي حالة فورًا
}

example:
c1 := make(chan string)
c2 := make(chan string)

go func() {
  time.Sleep(time.Second)
  c1 <- "من الأولى"
}()
go func() {
  time.Sleep(2 * time.Second)
  c2 <- "من الثانية"
}()

for i := 0; i < 2; i++ {
  select {
  case msg1 := <-c1:
    fmt.Println(msg1)
  case msg2 := <-c2:
    fmt.Println(msg2)
  }
}

