func safeDivide(a, b int) int {
  if b == 0 {
    panic("القسمة على صفر غير مسموحة")
  }
  return a / b
}

safeDivide(10, 0)   // panic: القسمة على صفر غير مسموحة

syntax:
func recover() any

defer func() {
  if r := recover(); r != nil {
    // تعامل مع القيمة r
  }
}()

example:
func safeCall() {
  defer func() {
    if r := recover(); r != nil {
      fmt.Println("تعافٍ من:", r)
    }
  }()
  panic("خطأ فادح غير متوقّع")
}

safeCall()
fmt.Println("البرنامج يكمل عاديًا بعد التعافي")

